#!/usr/bin/python3
"""Durable UDP meter collector for meter_id,sequence,reading datagrams."""
import base64
import csv
import datetime
import json
import os
import socket

BASE = os.path.dirname(os.path.abspath(__file__))
READINGS = os.path.join(BASE, "readings.csv")
MALFORMED = os.path.join(BASE, "malformed.log")
HEADER = ["meter_id", "sequence", "reading"]


def sync_append(path, text):
    with open(path, "a", encoding="utf-8", newline="") as stream:
        stream.write(text)
        stream.flush()
        os.fsync(stream.fileno())


def ensure_readings_file():
    if not os.path.exists(READINGS) or os.path.getsize(READINGS) == 0:
        sync_append(READINGS, ",".join(HEADER) + "\n")


def is_decimal_integer(value):
    return bool(value) and value.isascii() and value.isdigit()


def load_seen():
    seen = set()
    with open(READINGS, "r", encoding="utf-8", newline="") as stream:
        for row_number, row in enumerate(csv.reader(stream), 1):
            if row_number == 1 and row == HEADER:
                continue
            if len(row) != 3 or not row[0]:
                continue
            if not is_decimal_integer(row[1]) or not is_decimal_integer(row[2]):
                continue
            seen.add((row[0], int(row[1], 10)))
    return seen


def record_malformed(data, address, reason):
    record = {
        "time": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "source": "%s:%s" % address,
        "reason": reason,
        "payload": data.decode("ascii", "backslashreplace"),
        "payload_base64": base64.b64encode(data).decode("ascii"),
    }
    sync_append(MALFORMED, json.dumps(record, sort_keys=True) + "\n")


def parse_datagram(data):
    try:
        text = data.decode("ascii")
    except UnicodeDecodeError:
        raise ValueError("payload is not ASCII")
    text = text.rstrip("\r\n")
    fields = text.split(",")
    if len(fields) != 3:
        raise ValueError("expected exactly three comma-separated fields")
    meter_id, sequence_text, reading_text = fields
    if not meter_id or any(char in meter_id for char in "\r\n\x00"):
        raise ValueError("meter_id is empty or contains a control delimiter")
    if not is_decimal_integer(sequence_text):
        raise ValueError("sequence is not a nonnegative decimal integer")
    if not is_decimal_integer(reading_text):
        raise ValueError("reading is not a nonnegative decimal integer")
    return meter_id, int(sequence_text, 10), int(reading_text, 10)


def main():
    ensure_readings_file()
    seen = load_seen()
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.bind(("0.0.0.0", 9098))
    while True:
        data, address = sock.recvfrom(4096)
        try:
            meter_id, sequence, reading = parse_datagram(data)
        except (ValueError, OverflowError) as error:
            record_malformed(data, address, str(error))
            continue
        key = (meter_id, sequence)
        if key in seen:
            continue
        sync_append(READINGS, "%s,%d,%d\n" % (meter_id, sequence, reading))
        seen.add(key)


if __name__ == "__main__":
    main()
ANTRIEB_COLLECTOR_EOF
